    """Return the explicit local-snapshot/live-fetch boundary and preserved evidence contract."""

    return {
        "schema_version": 2,
        "adapter_id": WEB_INPUT_ADAPTER_ID,
        "implementation_status": "implemented",
        "input_modes": {
            "provided-static-snapshot": {
